dir:






























  &DefaultButton;




function dir$dmloaitd(p){
  this.constructor(p);
}
dir$dmloaitd.prototype = new DirEvent();
dir$dmloaitd.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmloaitd.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

dir$dmloaitdDisabledMasterField(p, g);

}

function dir$dmloaitdDisabledMasterField(p, g){

  if(p.valForm('ma_loai').trim() != '')
  {
    p.setDisabled('ma_loai', true);
  }
  else
  {
    p.setDisabled('ma_loai', false);
  }
}






	.control-label.ma_loai, .control-label.ten_loai
	{	
		//font-weight:bold;	
		color: #499b98;;
	}






